DROP TABLE IF EXISTS `conversations`;
CREATE TABLE `conversations`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'chat' COMMENT '会话类型: chat-聊天, comment-评论通知, collection-收藏通知',
  `user1_id` bigint NULL DEFAULT NULL COMMENT '用户1ID（聊天类型）',
  `user2_id` bigint NULL DEFAULT NULL COMMENT '用户2ID（聊天类型）',
  `last_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `last_message_time` datetime NULL DEFAULT NULL COMMENT '最后消息时间',
  `unread_count_user1` int NULL DEFAULT 0 COMMENT '用户1未读数',
  `unread_count_user2` int NULL DEFAULT 0 COMMENT '用户2未读数',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ai_service',
  `service_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'ai',
  `last_human_reply_time` datetime NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_conv_user1`(`user1_id` ASC) USING BTREE,
  INDEX `idx_conv_user2`(`user2_id` ASC) USING BTREE,
  INDEX `idx_conv_type`(`type` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会话表' ROW_FORMAT = DYNAMIC;

