  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知类型: comment-评论, collection-收藏',
  `from_user_id` bigint NULL DEFAULT NULL COMMENT '触发通知的用户ID',
  `post_id` bigint NULL DEFAULT NULL COMMENT '相关帖子ID',
  `comment_id` bigint NULL DEFAULT NULL COMMENT '相关评论ID',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通知内容',
  `is_read` tinyint(1) NULL DEFAULT 0 COMMENT '是否已读: 0-未读, 1-已读',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_notif_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_notif_type`(`type` ASC) USING BTREE,
  INDEX `idx_notif_time`(`create_time` ASC) USING BTREE,
  INDEX `fk_notif_from_user`(`from_user_id` ASC) USING BTREE,
  INDEX `fk_notif_post`(`post_id` ASC) USING BTREE,
  INDEX `fk_notif_comment`(`comment_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '通知表' ROW_FORMAT = DYNAMIC;

