INSERT INTO `official_contents` VALUES (18, 'homepage_publish_heritage', '[150,176,177,178,179,180]', 'homepage_heritage_selection', NULL, NULL, NULL, 1, 0, 10047, NULL, '2026-04-28 11:12:02', NULL);
INSERT INTO `official_contents` VALUES (19, '商河鼓子秧歌沉浸式体验日', '活动介绍\n走进\"中国民间艺术之乡\"商河县，在鼓子秧歌发源地亲身感受这项两千年国家级非遗的震撼魅力！活动由国家级非遗传承人亲自带队，从秧歌历史讲解到基础动作教学，再到完整阵型演练，带你沉浸式体验伞、鼓、棒、花四大角色的独特韵味。\n\n活动流程\n09:00-09:30 签到集合，观看鼓子秧歌纪录片\n09:30-10:30 传承人讲解秧歌历史与四大角色\n10:30-12:00 分组教学：鼓子基本步法与节奏训练\n12:00-13:30 午餐（品尝商河特色农家菜）\n13:30-15:30 完整阵型彩排与演练\n15:30-16:30 汇报表演，穿戴传统服饰合影留念\n16:30-17:00 颁发体验证书，活动结束\n\n注意事项\n建议穿着宽松运动服装及软底鞋；无需舞蹈基础，老少皆宜（12岁以下需家长陪同）；如遇大雨天气活动顺延一周。', 'activity', 'https://yayfolk.bhyy.online/jinan_ich/b2eb10ad-9832-4cef-9e68-ca032177ef91.jpg', NULL, NULL, 1, 0, 10047, 90, '2026-08-07 11:10:16', NULL);
INSERT INTO `official_contents` VALUES (20, '莱芜锡雕非遗手作工作坊', '活动介绍\n走进莱芜锡雕的世界，在国家级非遗传承人的亲自指导下，体验从锡锭到成品的完整制作过程。你将亲手锻打、錾刻一件属于自己的锡器作品，感受金属在锤下延展、纹样在刀尖绽放的奇妙过程。零基础可参加，作品可带回家！\n\n活动流程\n14:00-14:30 签到，参观锡雕作品展厅\n14:30-15:00 传承人讲解锡雕历史与工艺体系\n15:00-15:30 基础技法演示（锻打、錾刻、焊接）\n15:30-16:30 学员实操：锡片锤碟制作茶托/小摆件\n16:30-17:00 作品欣赏互评，传承人点评指导\n\n注意事项\n材料与工具由工作坊统一提供；作品完成后可当场带走；建议年满15周岁以上参加；操作过程中请听从指导以确保安全。', 'activity', 'https://yayfolk.bhyy.online/jinan_ich/71fb4453-f8f9-4edf-ad10-758deb2e4961.jpeg', NULL, NULL, 1, 0, 10047, 91, '2026-08-07 11:10:18', NULL);
INSERT INTO `official_contents` VALUES (21, '\"泉城有戏\"——吕剧经典折子戏专场', '演出介绍\n国庆之夜，泉城有戏！济南非遗文化馆特邀山东省吕剧院优秀演员联袂献演，精选三部吕剧经典折子戏，让您在佳节之夜感受最醇正的齐鲁乡音。演出配有电子字幕，吕剧入门者也能轻松欣赏。\n\n演出剧目\n《李二嫂改嫁》选段——吕剧里程碑之作，讲述农村妇女追求幸福的故事，唱腔脍炙人口\n《姊妹易嫁》选段——吕剧经典喜剧，姊妹错嫁妙趣横生，轻松欢快\n《小姑贤》选段——家庭伦理小戏，以情动人，唱做俱佳\n\n活动流程\n18:30-19:00 凭报名信息入场\n19:00-19:10 吕剧文化简介\n19:10-21:00 三出折子戏演出（含中场休息10分钟）\n21:00-21:30 演员交流互动，合影留念\n\n注意事项\n请提前15分钟入场；演出期间请将手机调至静音；1.2米以下儿童谢绝入场；凭报名信息现场核验。', 'activity', 'https://yayfolk.bhyy.online/jinan_ich/d32c3b30-b83c-4520-921e-6a0cd336cc98.jpg', NULL, NULL, 1, 0, 10047, 92, '2026-08-07 11:10:21', NULL);
INSERT INTO `official_contents` VALUES (22, '京剧脸谱体验工坊', '【活动简介】\n京剧作为中国五大戏曲剧种之一，被列入联合国教科文组织非物质文化遗产名录。本次工坊特别邀请国家级京剧传承人亲临指导，带领学员从认识京剧历史开始，深入了解生、旦、净、丑四大行当的脸谱艺术。\n\n【体验内容】\n1. 京剧基础知识讲解（30分钟）\n2. 脸谱绘制技法教学（60分钟）\n3. 脸谱佩戴与造型体验（30分钟）\n4. 作品展示与合影留念（30分钟）\n\n【成品规格】\n每位学员可完成一幅40x50cm京剧脸谱作品，作品完成后可带走收藏。\n\n【适宜人群】\n8-65周岁传统文化爱好者，无需绘画基础。\n\n【注意事项】\n请勿穿白色或浅色衣物，以免沾染色料。', 'activity', 'https://yayfolk.bhyy.online/activities/1777398398239/images/1.jpg', NULL, NULL, 1, 0, 10047, 89, '2026-08-07 11:10:23', NULL);
INSERT INTO `official_contents` VALUES (23, 'abcd', 'qwert', 'activity', 'https://yayfolk.bhyy.online/activities/1786264991707/images/1.png', NULL, NULL, 1, 0, 10047, 206, '2026-08-09 16:43:55', NULL);
