INSERT INTO `travel_post_comments` VALUES (4, 61, 10000, NULL, NULL, '你好，这是哪个博物馆的展品吗？', 0, '2026-05-01 00:46:34', 'zh');
INSERT INTO `travel_post_comments` VALUES (5, 125, 10011, NULL, NULL, '过几天我要去南京了，好像亲自做一个美丽的绒花做纪念', 0, '2026-08-09 14:58:05', 'zh');
INSERT INTO `travel_post_comments` VALUES (6, 72, 10011, NULL, NULL, '欢迎大家点击主页了解更多！！', 0, '2026-08-09 20:00:01', 'zh');
INSERT INTO `travel_post_comments` VALUES (7, 72, 10000, 6, 10011, '我看到那个绣体验活动请问10月份还有吗', 0, '2026-08-09 20:02:12', 'zh');
INSERT INTO `travel_post_comments` VALUES (8, 72, 10011, 7, 10000, '不好意思已经结束了，不过之后会持续举办的，静候', 0, '2026-08-09 20:03:49', 'zh');
INSERT INTO `travel_post_comments` VALUES (9, 72, 10011, NULL, NULL, '征集一下大家的体验志愿！', 0, '2026-08-09 20:04:24', 'zh');
INSERT INTO `travel_post_comments` VALUES (10, 72, 10000, 9, 10011, '我要报名+1', 0, '2026-08-09 20:05:08', 'zh');
INSERT INTO `travel_post_comments` VALUES (11, 2, 10000, NULL, NULL, '好详细的介绍！对福建游神一直很好奇，看完这篇涨了不少知识', 5, '2026-08-10 04:47:06', 'zh');
