INSERT INTO `travel_posts` VALUES (161, 10128, '特别适合静下心来慢慢做', '之前只在电视上看过，没想到能亲手体验！老师很有耐心，一步一步教，最后的成品虽然不够完美，但真的很有成就感。推荐对非遗感兴趣的朋友都来试试。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/161/1.jpg\"]', NULL, 'public', 1, 139, 1, '2026-08-02 08:18:06', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 6, 5, 0);
INSERT INTO `travel_posts` VALUES (162, 10020, '非常治愈的一次体验', '之前只在电视上看过，没想到能亲手体验！老师很有耐心，一步一步教，最后的成品虽然不够完美，但真的很有成就感。推荐对非遗感兴趣的朋友都来试试。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/162/1.jpg\"]', NULL, 'public', 1, 185, 1, '2026-07-17 08:10:54', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 12, 5, 1);
INSERT INTO `travel_posts` VALUES (163, 10125, '一次难忘的非遗之旅', '因为是周末的活动，正好放松一下。没想到这么有趣！做手工的过程中完全忘记了工作压力，特别解压。成品拿回家当装饰品，朋友们都说好看。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/163/1.jpg\"]', NULL, 'public', 1, 182, 1, '2026-08-06 06:45:26', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 18, 4, 0);
INSERT INTO `travel_posts` VALUES (164, 10138, '下次还要带朋友来', '之前只在电视上看过，没想到能亲手体验！老师很有耐心，一步一步教，最后的成品虽然不够完美，但真的很有成就感。推荐对非遗感兴趣的朋友都来试试。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/164/1.jpg\"]', NULL, 'public', 1, 169, 1, '2026-07-27 02:21:39', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 26, 5, 0);
INSERT INTO `travel_posts` VALUES (165, 10020, '学到了很多非遗知识', '第一次接触这个手艺，比想象中更需要耐心和细心。但正是因为这种慢工出细活的过程，让人完全沉浸在当下，忘记时间的流逝。非常治愈的体验。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/165/1.jpg\"]', NULL, 'public', 1, 138, 1, '2026-07-24 23:12:51', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 30, 5, 0);
INSERT INTO `travel_posts` VALUES (166, 10110, '终于亲身体验了这门手艺', '一直想深入了解非遗文化，这次活动是个很好的切入点。从理论到实践都有涉及，不仅学会了基本技法，还了解了很多民俗故事。五星好评！', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/166/1.jpg\"]', NULL, 'public', 1, 198, 1, '2026-08-03 05:03:21', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 30, 5, 0);
INSERT INTO `travel_posts` VALUES (167, 10139, '非常治愈的一次体验', '一直想深入了解非遗文化，这次活动是个很好的切入点。从理论到实践都有涉及，不仅学会了基本技法，还了解了很多民俗故事。五星好评！', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/167/1.jpg\"]', NULL, 'public', 1, 211, 1, '2026-04-18 17:37:01', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 33, 4, 0);
INSERT INTO `travel_posts` VALUES (168, 10116, '非遗文化的魅力', '作为手工爱好者，这个活动完美满足了我的期待。老师不仅教技术，还会讲背后的文化故事，让人更加理解每一道工序的意义。做出来的作品摆在家里特别好看。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/168/1.jpg\"]', NULL, 'public', 1, 95, 1, '2026-05-01 05:19:34', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 34, 5, 1);
INSERT INTO `travel_posts` VALUES (169, 10146, '学到了很多非遗知识', '朋友们都以为我在外面买的手作成品，不敢相信是我自己做的！老师的教学方法很好，即使零基础也能做出不错的效果。已经开始期待下次的活动了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/169/1.jpg\"]', NULL, 'public', 1, 104, 1, '2026-07-10 22:47:35', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 35, 5, 0);
INSERT INTO `travel_posts` VALUES (170, 10111, '非遗文化的魅力', '整个流程设计得很合理，不会让人觉得太难也不会太简单。老师的指导恰到好处，既给了发挥空间，又不会让人走太多弯路。非常满意的体验。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/170/1.jpg\"]', NULL, 'public', 1, 199, 1, '2026-05-15 15:31:43', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 36, 4, 0);
INSERT INTO `travel_posts` VALUES (171, 10130, '一次难忘的非遗之旅', '第一次知道还有这么精美的传统手艺，真是大开眼界。从准备材料到完成作品，每一步都很有讲究。虽然只学了皮毛，但已经深深被吸引住了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/171/1.jpg\"]', NULL, 'public', 1, 182, 1, '2026-04-25 20:03:15', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 37, 4, 0);
INSERT INTO `travel_posts` VALUES (172, 10144, '传统文化的新体验', '带孩子一起来的，孩子玩得很开心，也学到了很多传统手工艺的知识。这种寓教于乐的方式特别好，以后会经常关注类似的活动。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/172/1.jpg\"]', NULL, 'public', 1, 174, 1, '2026-06-18 00:00:20', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 38, 5, 0);
INSERT INTO `travel_posts` VALUES (173, 10109, '终于亲身体验了这门手艺', '因为是周末的活动，正好放松一下。没想到这么有趣！做手工的过程中完全忘记了工作压力，特别解压。成品拿回家当装饰品，朋友们都说好看。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/173/1.jpg\"]', NULL, 'public', 1, 140, 1, '2026-04-05 00:13:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 38, 4, 0);
