INSERT INTO `travel_posts` VALUES (176, 10020, '传统文化的新体验', '带孩子一起来的，孩子玩得很开心，也学到了很多传统手工艺的知识。这种寓教于乐的方式特别好，以后会经常关注类似的活动。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/176/1.jpg\"]', NULL, 'public', 1, 205, 1, '2026-07-14 23:42:56', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 41, 5, 0);
INSERT INTO `travel_posts` VALUES (177, 10130, '一次难忘的非遗之旅', '老师是真正的匠人，从选题、配色到技法都讲得很到位。能感受到他们对传统手工艺的热爱和执着，这种精神很感染人。体验完后对非遗有了全新的认识。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/177/1.jpg\"]', NULL, 'public', 1, 164, 1, '2026-06-27 04:44:23', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 42, 4, 0);
INSERT INTO `travel_posts` VALUES (178, 10118, '比想象中有趣多了', '活动超出了预期！原本以为只是简单体验，没想到老师讲得这么深入，从历史渊源到现代传承都涉及到了。做出来的作品虽然不是最完美的，但倾注了心意，很有纪念价值。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/178/1.jpg\"]', NULL, 'public', 1, 208, 1, '2026-06-03 16:16:44', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 42, 5, 1);
