INSERT INTO `travel_posts` VALUES (198, 10124, '完成作品的那一刻太有成就感了', '朋友们都以为我在外面买的手作成品，不敢相信是我自己做的！老师的教学方法很好，即使零基础也能做出不错的效果。已经开始期待下次的活动了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/198/1.jpg\"]', NULL, 'public', 1, 70, 1, '2026-07-16 11:55:48', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 88, 5, 0);
INSERT INTO `travel_posts` VALUES (199, 10007, '强烈推荐给大家', '活动安排得很紧凑，从了解历史文化背景到亲手制作，整个过程都很流畅。材料也很讲究，能感受到组织方的用心。已经推荐给身边的朋友了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/199/1.jpg\"]', NULL, 'public', 1, 150, 1, '2026-05-01 12:07:15', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 89, 5, 0);
INSERT INTO `travel_posts` VALUES (200, 10131, '强烈推荐给大家', '作为手工爱好者，这个活动完美满足了我的期待。老师不仅教技术，还会讲背后的文化故事，让人更加理解每一道工序的意义。做出来的作品摆在家里特别好看。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/200/1.jpg\"]', NULL, 'public', 1, 215, 1, '2026-05-03 12:13:21', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 89, 4, 0);
INSERT INTO `travel_posts` VALUES (201, 10140, '终于亲身体验了这门手艺', '一直想深入了解非遗文化，这次活动是个很好的切入点。从理论到实践都有涉及，不仅学会了基本技法，还了解了很多民俗故事。五星好评！', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/201/1.jpg\"]', NULL, 'public', 1, 111, 1, '2026-04-30 20:41:35', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 89, 5, 0);
INSERT INTO `travel_posts` VALUES (202, 10116, '深入了解传统文化', '朋友们都以为我在外面买的手作成品，不敢相信是我自己做的！老师的教学方法很好，即使零基础也能做出不错的效果。已经开始期待下次的活动了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/202/1.jpg\"]', NULL, 'public', 1, 108, 1, '2026-05-01 19:51:33', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 89, 4, 0);
INSERT INTO `travel_posts` VALUES (203, 10130, '非遗文化的魅力', '朋友们都以为我在外面买的手作成品，不敢相信是我自己做的！老师的教学方法很好，即使零基础也能做出不错的效果。已经开始期待下次的活动了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/203/1.jpg\"]', NULL, 'public', 1, 96, 1, '2026-08-09 23:42:45', '2026-08-09 23:42:45', NULL, NULL, NULL, 'normal', 91, 4, 0);
INSERT INTO `travel_posts` VALUES (204, 10144, '学到了很多非遗知识', '跟闺蜜一起来的，两个人一起做手工特别开心。活动结束后还互相交流了心得，约定下次再来体验别的项目。这种文化体验比单纯逛街有意思多了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/204/1.jpg\"]', NULL, 'public', 1, 193, 1, '2026-08-08 04:08:42', '2026-08-08 04:08:42', NULL, NULL, NULL, 'normal', 146, 5, 1);
INSERT INTO `travel_posts` VALUES (205, 10136, '下次还要带朋友来', '活动安排得很紧凑，从了解历史文化背景到亲手制作，整个过程都很流畅。材料也很讲究，能感受到组织方的用心。已经推荐给身边的朋友了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/205/1.jpg\"]', NULL, 'public', 1, 182, 1, '2026-08-09 00:16:36', '2026-08-09 00:16:36', NULL, NULL, NULL, 'normal', 146, 5, 0);
INSERT INTO `travel_posts` VALUES (206, 10124, '一次难忘的非遗之旅', '因为是周末的活动，正好放松一下。没想到这么有趣！做手工的过程中完全忘记了工作压力，特别解压。成品拿回家当装饰品，朋友们都说好看。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/206/1.jpg\"]', NULL, 'public', 1, 75, 1, '2026-08-11 21:04:35', '2026-08-11 01:41:50', NULL, NULL, NULL, 'normal', 148, 4, 1);
INSERT INTO `travel_posts` VALUES (207, 10147, '传统文化的新体验', '老师傅的手艺真的令人叹为观止，演示的时候大家都看呆了。后来自己动手才发现看着简单做着难，但正因为有挑战才有收获。来体验绝对不会后悔。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/207/1.jpg\"]', NULL, 'public', 1, 168, 1, '2026-08-11 21:30:00', '2026-08-11 01:41:56', NULL, NULL, NULL, 'normal', 148, 5, 0);
INSERT INTO `travel_posts` VALUES (208, 10140, '沉浸式文化之旅', '第一次接触这个手艺，比想象中更需要耐心和细心。但正是因为这种慢工出细活的过程，让人完全沉浸在当下，忘记时间的流逝。非常治愈的体验。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/208/1.jpg\"]', NULL, 'public', 1, 189, 1, '2026-08-09 09:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 152, 5, 0);
INSERT INTO `travel_posts` VALUES (209, 10119, '下次还要带朋友来', '带孩子一起来的，孩子玩得很开心，也学到了很多传统手工艺的知识。这种寓教于乐的方式特别好，以后会经常关注类似的活动。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/209/1.jpg\"]', NULL, 'public', 1, 165, 1, '2026-08-09 02:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 153, 5, 0);
INSERT INTO `travel_posts` VALUES (210, 10112, '沉浸式文化之旅', '一直想深入了解非遗文化，这次活动是个很好的切入点。从理论到实践都有涉及，不仅学会了基本技法，还了解了很多民俗故事。五星好评！', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/210/1.jpg\"]', NULL, 'public', 1, 149, 1, '2026-08-09 21:00:00', '2026-08-11 01:42:26', NULL, NULL, NULL, 'normal', 153, 5, 1);
INSERT INTO `travel_posts` VALUES (211, 10119, '深入了解传统文化', '活动安排得很紧凑，从了解历史文化背景到亲手制作，整个过程都很流畅。材料也很讲究，能感受到组织方的用心。已经推荐给身边的朋友了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/211/1.jpg\"]', NULL, 'public', 1, 115, 1, '2026-08-09 04:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 160, 5, 0);
INSERT INTO `travel_posts` VALUES (212, 10122, '传统文化的新体验', '因为是周末的活动，正好放松一下。没想到这么有趣！做手工的过程中完全忘记了工作压力，特别解压。成品拿回家当装饰品，朋友们都说好看。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/212/1.jpg\"]', NULL, 'public', 1, 105, 1, '2026-08-09 12:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 160, 5, 1);
INSERT INTO `travel_posts` VALUES (213, 10117, '非常治愈的一次体验', '活动超出了预期！原本以为只是简单体验，没想到老师讲得这么深入，从历史渊源到现代传承都涉及到了。做出来的作品虽然不是最完美的，但倾注了心意，很有纪念价值。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/213/1.jpg\"]', NULL, 'public', 1, 107, 1, '2026-08-09 07:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 161, 4, 0);
INSERT INTO `travel_posts` VALUES (214, 10136, '终于亲身体验了这门手艺', '活动场地布置得很有氛围，一进门就感受到了传统文化的魅力。材料准备得很充足，每个人都能按照自己的节奏来。三个小时下来，收获的不仅是一件作品，更是一段美好的回忆。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/214/1.jpg\"]', NULL, 'public', 1, 212, 1, '2026-08-09 21:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 164, 5, 0);
INSERT INTO `travel_posts` VALUES (215, 10109, '这次体验太棒了！', '朋友们都以为我在外面买的手作成品，不敢相信是我自己做的！老师的教学方法很好，即使零基础也能做出不错的效果。已经开始期待下次的活动了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/215/1.jpg\"]', NULL, 'public', 1, 158, 1, '2026-08-09 09:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 164, 4, 1);
INSERT INTO `travel_posts` VALUES (216, 10111, '深入了解传统文化', '之前只在电视上看过，没想到能亲手体验！老师很有耐心，一步一步教，最后的成品虽然不够完美，但真的很有成就感。推荐对非遗感兴趣的朋友都来试试。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/216/1.jpg\"]', NULL, 'public', 1, 121, 1, '2026-08-09 13:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 166, 5, 1);
INSERT INTO `travel_posts` VALUES (217, 10124, '值得一试的手作体验', '跟闺蜜一起来的，两个人一起做手工特别开心。活动结束后还互相交流了心得，约定下次再来体验别的项目。这种文化体验比单纯逛街有意思多了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/217/1.jpg\"]', NULL, 'public', 1, 183, 1, '2026-08-09 06:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 167, 5, 0);
INSERT INTO `travel_posts` VALUES (218, 10146, '非遗文化的魅力', '老师是真正的匠人，从选题、配色到技法都讲得很到位。能感受到他们对传统手工艺的热爱和执着，这种精神很感染人。体验完后对非遗有了全新的认识。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/218/1.jpg\"]', NULL, 'public', 1, 163, 1, '2026-08-07 10:06:55', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 171, 5, 0);
