INSERT INTO `travel_posts` VALUES (220, 10140, '完成作品的那一刻太有成就感了', '第一次知道还有这么精美的传统手艺，真是大开眼界。从准备材料到完成作品，每一步都很有讲究。虽然只学了皮毛，但已经深深被吸引住了。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/220/1.jpg\"]', NULL, 'public', 1, 190, 1, '2026-08-09 12:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 179, 5, 1);
