INSERT INTO `travel_posts` VALUES (225, 10131, '收获满满的一天', '整个流程设计得很合理，不会让人觉得太难也不会太简单。老师的指导恰到好处，既给了发挥空间，又不会让人走太多弯路。非常满意的体验。', 'review', 'activity', 'passed', NULL, '[\"https://yayfolk.bhyy.online/posts/225/1.jpg\"]', NULL, 'public', 1, 216, 1, '2026-08-09 21:00:00', '2026-08-11 01:30:13', NULL, NULL, NULL, 'normal', 199, 4, 0);
